import json, sys

BASE = "https://freya-bank-mock-team.egemenayrac.workers.dev/v1"

SETUP_CODE = r'''
import datetime
try:
    HOL = set(['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'])
    GUN = ['Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma', 'Cumartesi', 'Pazar']
    AY = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
    now_s = str(vars.get('now') or '')
    try:
        now = datetime.datetime.fromisoformat(now_s[:16])
    except Exception:
        now = datetime.datetime.now()
    today = now.date()
    def isbd(d):
        return d.weekday() < 5 and d.isoformat() not in HOL
    def nextbd(d):
        d = d + datetime.timedelta(days=1)
        while not isbd(d):
            d = d + datetime.timedelta(days=1)
        return d
    def nth_bd(n):
        d = today
        for i in range(n):
            d = nextbd(d)
        return d
    def lab(d):
        return d.isoformat() + ' ' + GUN[d.weekday()] + ' (' + str(d.day) + ' ' + AY[d.month] + ')'
    def first_ok(d):
        while not isbd(d):
            d = d + datetime.timedelta(days=1)
        return d
    t = vars.get('title')
    fn = str(vars.get('first_name') or '')
    vars['hitap'] = fn + (' Hanım' if str(t).strip().lower() in ('ms', 'mrs', 'miss') else ' Bey')
    vars['today_label'] = lab(today)
    vars['now_time'] = now.strftime('%H:%M')
    dl = {'early': nth_bd(12), 'late': nth_bd(7)}
    vars['deadline_early'] = lab(dl['early'])
    vars['deadline_late'] = lab(dl['late'])
    # last business day of this week (attempt 1)
    monday = today - datetime.timedelta(days=today.weekday())
    def last_bd_of_week(mon):
        d = mon + datetime.timedelta(days=4)
        while d >= mon and not isbd(d):
            d = d - datetime.timedelta(days=1)
        return d
    lw = last_bd_of_week(monday)
    if lw <= today:
        lw = last_bd_of_week(monday + datetime.timedelta(days=7))
    def tables(band):
        D = dl[band]
        lines = []
        for i in range(0, 50):
            d = today + datetime.timedelta(days=i)
            if isbd(d) and d <= D:
                s = 'iş günü, kabul edilebilir -> bu tarihi kaydet: ' + d.isoformat()
            elif d > D:
                s = 'SON TARİHTEN SONRA -> kaydedebileceğiniz en geç tarihin ' + lab(D) + ' olduğunu söyle ve onu öner'
            else:
                n = first_ok(d)
                why = 'banka tatili' if d.isoformat() in HOL else 'hafta sonu'
                if n <= D:
                    s = why + ', iş günü değil -> bir sonraki iş günü ' + lab(n) + ' öner'
                else:
                    s = why + ', iş günü değil -> en geç tarih ' + lab(D) + ', onu öner'
            lines.append(lab(d) + ': ' + s)
        return '\n'.join(lines)
    vars['date_table_early'] = tables('early')
    vars['date_table_late'] = tables('late')
    rel = []
    rel.append('bugün = ' + lab(today))
    rel.append('yarın = ' + lab(today + datetime.timedelta(days=1)))
    rel.append('öbür gün = ' + lab(today + datetime.timedelta(days=2)))
    for k in range(7):
        this_d = monday + datetime.timedelta(days=k)
        next_d = this_d + datetime.timedelta(days=7)
        tail = '' if this_d >= today else ' (geçti; müşteriye hangi günü kastettiğini sor)'
        rel.append('bu ' + GUN[k] + ' = ' + lab(this_d) + tail)
        rel.append('haftaya ' + GUN[k] + ' = ' + lab(next_d))
    rel.append('bu haftanın son iş günü (1. ikna denemesinin tarihi) = ' + lab(lw))
    rel.append('"haftaya", "ay sonu", "maaşım yatınca", "iki hafta sonra", "önümüzdeki hafta" gibi gün içermeyen ifadeler BELİRSİZDİR -> bir kez kesin günü sor')
    vars['relative_dates'] = '\n'.join(rel)
    vars['attempt1_date'] = lab(lw)
    # callback window
    cb = []
    if isbd(today) and now.strftime('%H:%M') < '19:00':
        start = max(now.strftime('%H:%M'), '10:00')
        cb.append('BUGÜN ' + lab(today) + ': ' + start + ' sonrası ile 19:00 arası (19:00 dahil) uygun')
    else:
        cb.append('BUGÜN ' + lab(today) + ': uygun değil')
    nb = nextbd(today)
    cb.append('SONRAKİ İŞ GÜNÜ ' + lab(nb) + ': 10:00 ile 19:00 arası (ikisi dahil) uygun')
    cb.append('Diğer tüm günler ve bu saatlerin dışı UYGUN DEĞİL. (yarın = ' + lab(today + datetime.timedelta(days=1)) + ')')
    vars['callback_window'] = '\n'.join(cb)
except Exception as e:
    vars['hitap'] = str(vars.get('first_name') or '')
    vars['setup_error'] = str(e)
'''

def hook(kind):
    common = r'''
try:
    r = result if isinstance(result, dict) else {}
    try:
        r.pop('header', None)
    except Exception:
        pass
    d = r.get('data')
    sc = r.get('status_code')
    ok = isinstance(d, dict) and d.get('ok') is True
    if not isinstance(d, dict):
        d = {}
    err = str(d.get('error') or r.get('message') or '')
'''
    if kind == 'verify':
        body = r'''
    if ok:
        if d.get('all_verified') is True:
            d['what_to_do_next'] = 'Kimlik doğrulandı. Hiçbir şey söyleme, sistem devam edecek.'
        elif d.get('verified') is True:
            d['what_to_do_next'] = 'Bu cevap doğru. Şimdi sıradaki güvenlik sorusunu sor (telefon numarasının son dört hanesi).'
        elif d.get('hint') == 'day_month_swapped':
            d['what_to_do_next'] = 'Gün ve ay ters söylenmiş olabilir. Müşteriden doğum tarihini ayı kelimeyle (ör. on dört Mart) söylemesini iste. Bu yanlış cevap sayılmaz.'
        else:
            left = d.get('wrong_answers_left')
            try:
                left = int(left)
            except Exception:
                left = 1
            if left <= 0 or str(d.get('locked')).lower() == 'true':
                d['what_to_do_next'] = 'Üç yanlış cevap: kontrol bitti. Borç, ürün, tutar SÖYLEME. Müşteriye mobil uygulamayı ya da bir şubeyi kullanmasını söyle, teşekkür edip vedalaş ve close_call(outcome=not_verified, reason=failed) çağır.'
            else:
                d['what_to_do_next'] = 'Cevap yanlış. Kalan hak: ' + str(left) + '. Aynı soruyu kibarca bir kez daha sor. Doğru cevabı ima etme.'
    else:
        d = {'ok': False, 'error': err or 'service failed', 'what_to_do_next': 'Cevap sistemde kontrol edilemedi (yanlış sayılmadı). Müşteriden aynı cevabı tekrar, tarihse gün ay yıl olarak, istemeden önce verify_identity\'yi aynı cevapla bir kez daha dene; yine olmazsa cevabı tekrar iste.'}
    r['data'] = d
except Exception:
    pass
'''
    elif kind == 'account':
        body = r'''
    if ok:
        ps = d.get('products') or []
        p = ps[0] if isinstance(ps, list) and ps else {}
        try:
            dlate = int(p.get('days_late'))
        except Exception:
            dlate = 0
        band = 'late' if dlate >= 8 else 'early'
        typ = p.get('type')
        if typ == 'credit_card':
            pname = str(p.get('card_last4') or '') + ' ile biten kredi kartınız'
            floor = p.get('minimum_payment')
        elif typ == 'car_loan':
            pname = 'taşıt krediniz'
            floor = p.get('instalment_amount')
        else:
            pname = 'ihtiyaç krediniz'
            floor = p.get('instalment_amount')
        dl = vars.get('deadline_late') if band == 'late' else vars.get('deadline_early')
        d['product_id_to_use'] = p.get('product_id')
        d['urun_adi'] = pname
        d['tam_tutar_TL'] = p.get('past_due')
        d['alt_sinir_TL'] = floor
        d['bant'] = ('GEÇ bant (8-45 gün): son tarih ' + str(dl) + ', 2 ikna denemesi; TARİH TABLOSU: GEÇ BANT tablosunu kullan') if band == 'late' else ('ERKEN bant (1-7 gün): son tarih ' + str(dl) + ', 1 ikna denemesi; TARİH TABLOSU: ERKEN BANT tablosunu kullan')
        d['what_to_do_next'] = 'Şimdi söyle: Tahsilat ekibinden gecikmiş bir ödeme için aradığını; ' + pname + ' için ' + str(p.get('past_due')) + ' TL tutarın ' + str(dlate) + ' gündür geciktiğini (tutarı kelimeyle oku). Sonra sor: "Bu ödemeyi bugün yapabilir misiniz?"'
    else:
        d = {'ok': False, 'error': err or 'service failed', 'what_to_do_next': 'Hesap bilgisi alınamadı. get_account\'u bir kez daha çağır. Yine olmazsa müşteriye şu an bilgiye ulaşamadığını söyle, teşekkür edip vedalaş ve close_call(outcome=no_promise, reason=service_error) çağır.'}
    r['data'] = d
except Exception:
    pass
'''
    elif kind == 'promise':
        body = r'''
    dup = any(w in err.lower() for w in ['already', 'duplicate', 'exists', 'zaten'])
    if ok or dup:
        d['ok'] = True
        vars['promise_recorded'] = 'yes'
        d['what_to_do_next'] = 'Söz KAYDEDİLDİ. Müşteriye sözün kaydedildiğini söyle ve aynen şu cümleyi söyle: "Bu sözü onaylayan bir kısa mesaj alacaksınız." Sonra teşekkür edip vedalaş ve close_call(outcome=promise) çağır. create_promise\'i bir daha ÇAĞIRMA.'
    else:
        try:
            n = int(vars.get('cp_fail') or 0) + 1
        except Exception:
            n = 1
