def api_tool(name, path, fields, required, desc, kind, mapping=None):
    props = {
        "url": {"type": "string", "default": BASE + path},
        "method": {"type": "string", "default": "POST"},
        "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
        "body": {"type": "object", "required": required, "properties": fields},
    }
    t = {
        "type": "function",
        "config": {"timeoutMs": 12000, "maxRetries": 0},
        "function": {"name": name, "handler": "__function__:api_call", "description": desc,
                     "parameters": {"type": "object", "properties": props}},
        "post_process_code": hook(kind),
    }
    if mapping:
        t["response_mapping"] = mapping
    return t

